using FluNET.Prompt;
using FluNET.Prompt.Surface;
namespace FluNET.Language.Resources;
public enum ResourceReadIntent{Get,Load} public enum ResourceCapability{FileRead,NetworkRead,EnvironmentRead,SecretRead,DatabaseRead}
public sealed record ResourceProviderContext(ResourceDescriptor Descriptor,string OutputVariable,SurfaceCommandSyntax SurfaceCommand,SurfaceValueSyntax Source,PromptGrammar Grammar,ResourceReadIntent Intent);
public sealed record ResourceProviderResult(IReadOnlyList<CommandSyntax> Commands,string? ErrorCode=null,string? ErrorMessage=null){public bool IsSuccess=>ErrorCode is null;public static ResourceProviderResult Error(string code,string message)=>new([],code,message);}
public interface IResourceProvider{string Id{get;}IReadOnlyList<ResourceCapability> RequiredCapabilities=>[];bool CanHandle(ResourceDescriptor descriptor);ResourceProviderResult LowerRead(ResourceProviderContext context);} public interface IResourceProviderRegistry{IReadOnlyList<IResourceProvider> Providers{get;}IResourceProvider? Resolve(ResourceDescriptor descriptor);} internal sealed record ResourceProviderRegistration(Type ProviderType,Func<IServiceProvider,IResourceProvider>Create);
public sealed class ResourceProviderRegistry:IResourceProviderRegistry{private readonly IResourceProvider[]_providers;internal ResourceProviderRegistry(IServiceProvider services,IEnumerable<ResourceProviderRegistration> registrations){_providers=new IResourceProvider[]{new FileResourceProvider(),new HttpResourceProvider(),new EnvironmentResourceProvider(),new SecretResourceProvider()}.Concat(registrations.Select(r=>r.Create(services))).ToArray();string[]d=_providers.GroupBy(p=>p.Id,StringComparer.OrdinalIgnoreCase).Where(g=>g.Count()>1).Select(g=>g.Key).ToArray();if(d.Length>0)throw new LanguageDefinitionException($"Resource provider ids must be unique: {string.Join(", ",d)}.");}public IReadOnlyList<IResourceProvider> Providers=>_providers;public IResourceProvider? Resolve(ResourceDescriptor descriptor){IResourceProvider[]m=_providers.Where(p=>p.CanHandle(descriptor)).ToArray();return m.Length switch{0=>null,1=>m[0],_=>throw new LanguageDefinitionException($"Resource '{descriptor.Reference.DisplayName}' matches multiple providers: {string.Join(", ",m.Select(i=>i.Id))}.")};}}
public sealed class FileResourceProvider:IResourceProvider{public string Id=>"core.file";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.FileRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is FileResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){FileResourceReference f=(FileResourceReference)c.Descriptor.Reference;if(f.IsPattern){if(c.Descriptor.Format!=ResourceFormat.Json)return ResourceProviderResult.Error("FLN225",$"Glob LOAD currently supports JSON patterns; '{c.Descriptor.Format}' needs a collection codec.");return new([Command("LOADGLOB",c,f.Path)]);}string verb=c.Descriptor.Format switch{ResourceFormat.Csv=>"LOADCSV",ResourceFormat.Xml=>"LOADXML",ResourceFormat.Binary=>"LOADBINARY",ResourceFormat.Image=>"LOADIMAGE",_=>string.Empty};if(verb.Length>0)return new([Command(verb,c,f.Path)]);string q=c.Descriptor.Format switch{ResourceFormat.Json=>"CONFIG",ResourceFormat.Text=>"TEXT",_=>string.Empty};if(q.Length==0)return ResourceProviderResult.Error("FLN224",$"No canonical file decoder is registered for format '{c.Descriptor.Format}'.");return new([new CommandSyntax([T("LOAD",PromptTokenKind.Word,c.SurfaceCommand.Span.Start),T(q,PromptTokenKind.Word,c.Source.Span.Start),T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),T("FROM",PromptTokenKind.Word,c.Source.Span.Start),T($"{{{f.Path}}}",PromptTokenKind.Reference,c.Source.Span.Start)],c.Grammar)]);}private static CommandSyntax Command(string v,ResourceProviderContext c,string p)=>new([T(v,PromptTokenKind.Word,c.SurfaceCommand.Span.Start),T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),T("FROM",PromptTokenKind.Word,c.Source.Span.Start),T($"{{{p}}}",PromptTokenKind.Reference,c.Source.Span.Start)],c.Grammar);private static PromptToken T(string x,PromptTokenKind k,int s)=>new(x,k,Math.Max(0,s),0);}
public sealed class HttpResourceProvider:IResourceProvider{public string Id=>"core.http";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.NetworkRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is HttpResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){if(c.Intent!=ResourceReadIntent.Get)return ResourceProviderResult.Error("FLN223","HTTP resources belong to GET rather than LOAD.");string verb=c.Descriptor.Format switch{ResourceFormat.Json=>"GETHTTP",ResourceFormat.Text=>"GETHTTPTEXT",ResourceFormat.Csv=>"GETHTTPCSV",ResourceFormat.Xml=>"GETHTTPXML",ResourceFormat.Binary=>"GETHTTPBINARY",ResourceFormat.Image=>"GETHTTPIMAGE",_=>string.Empty};if(verb.Length==0)return ResourceProviderResult.Error("FLN233",$"No typed HTTP decoder contract exists for '{c.Descriptor.Format}'.");Uri uri=((HttpResourceReference)c.Descriptor.Reference).Uri;return new([new CommandSyntax([T(verb,PromptTokenKind.Word,c.SurfaceCommand.Span.Start),T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),T("FROM",PromptTokenKind.Word,c.Source.Span.Start),T($"{{{uri}}}",PromptTokenKind.Reference,c.Source.Span.Start)],c.Grammar)]);}private static PromptToken T(string x,PromptTokenKind k,int s)=>new(x,k,Math.Max(0,s),0);}
public sealed class EnvironmentResourceProvider:IResourceProvider{public string Id=>"core.environment";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.EnvironmentRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is EnvironmentResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){if(c.Intent!=ResourceReadIntent.Get)return ResourceProviderResult.Error("FLN223","Environment resources belong to GET rather than LOAD.");string n=((EnvironmentResourceReference)c.Descriptor.Reference).Name;return new([new CommandSyntax([T("GETENV",PromptTokenKind.Word,c.SurfaceCommand.Span.Start),T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),T("FROM",PromptTokenKind.Word,c.Source.Span.Start),T($"{{{n}}}",PromptTokenKind.Reference,c.Source.Span.Start)],c.Grammar)]);}private static PromptToken T(string x,PromptTokenKind k,int s)=>new(x,k,Math.Max(0,s),0);}
public sealed class SecretResourceProvider:IResourceProvider{public string Id=>"core.secret";public IReadOnlyList<ResourceCapability>RequiredCapabilities=>[ResourceCapability.SecretRead];public bool CanHandle(ResourceDescriptor d)=>d.Reference is SecretResourceReference;public ResourceProviderResult LowerRead(ResourceProviderContext c){if(c.Intent!=ResourceReadIntent.Get)return ResourceProviderResult.Error("FLN307","Secrets belong to GET rather than LOAD.");string n=((SecretResourceReference)c.Descriptor.Reference).Name;return new([new CommandSyntax([T("GETSECRET",PromptTokenKind.Word,c.SurfaceCommand.Span.Start),T($"[{c.OutputVariable}]",PromptTokenKind.Variable,c.Source.Span.Start),T("FROM",PromptTokenKind.Word,c.Source.Span.Start),T($"{{{n}}}",PromptTokenKind.Reference,c.Source.Span.Start)],c.Grammar)]);}private static PromptToken T(string x,PromptTokenKind k,int s)=>new(x,k,Math.Max(0,s),0);}
